<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/auth.php';$user=require_role('donor');$requestId=filter_input(INPUT_GET,'request',FILTER_VALIDATE_INT) ?: filter_input(INPUT_POST,'request_id',FILTER_VALIDATE_INT);if(!$requestId){redirect('donor/browse.php');}$pdo=db();
$stmt=$pdo->prepare('SELECT cr.*,c.organization_name FROM clothing_requests cr JOIN charities c ON c.id=cr.charity_id WHERE cr.id=? AND cr.status="active"');$stmt->execute([$requestId]);$request=$stmt->fetch();if(!$request){flash('error','That clothing request is not accepting pledges.');redirect('donor/browse.php');}$requirements=request_requirements($pdo,$requestId);$errors=[];$quantities=[];
if(is_post()){verify_csrf();$notes=trim($_POST['donor_notes']??'');$input=$_POST['quantity']??[];$items=[];foreach($requirements as $r){$qty=filter_var($input[$r['id']]??0,FILTER_VALIDATE_INT,['options'=>['min_range'=>0]]) ?: 0;$quantities[$r['id']]=$qty;if($qty>0){if($qty>(int)$r['quantity_remaining'])$errors[]='You can pledge up to '.$r['quantity_remaining'].' '.$r['category'].' item(s) for this request.';$items[]=['id'=>$r['id'],'qty'=>$qty];}}
 if(!$items)$errors[]='Choose at least one item to pledge.';if(mb_strlen($notes)>1000)$errors[]='Your note is too long.';
 if(!$errors){$pdo->beginTransaction();try{$stmt=$pdo->prepare('INSERT INTO donation_pledges (donor_id,request_id,status,donor_notes) VALUES (?,?,"pending",?)');$stmt->execute([$user['id'],$requestId,$notes?:null]);$pledgeId=(int)$pdo->lastInsertId();$itemStmt=$pdo->prepare('INSERT INTO donation_items (pledge_id,request_requirement_id,category,size_label,quantity) SELECT ?,id,category,size_label,? FROM request_requirements WHERE id=?');foreach($items as $item)$itemStmt->execute([$pledgeId,$item['qty'],$item['id']]);$recipient=$pdo->prepare('SELECT c.user_id FROM clothing_requests cr JOIN charities c ON c.id=cr.charity_id WHERE cr.id=?');$recipient->execute([$requestId]);if($charityUserId=(int)$recipient->fetchColumn())create_notification($pdo,$charityUserId,'pledge','A new pledge is waiting','A donor pledged clothing for '.$request['title'].'.','charity/donations.php');log_activity($pdo,'pledged clothing for '.$request['title'],(int)$user['id'],'pledge',$pledgeId);$pdo->commit();flash('success','Your pledge was sent to '.$request['organization_name'].'. They’ll review it shortly.');redirect('donor/dashboard.php');}catch(Throwable $e){$pdo->rollBack();$errors[]='We could not save the pledge. Please try again.';}}
}
$pageTitle='Make a pledge';require __DIR__ . '/../includes/header.php'; ?>
<section class="page-hero"><div class="shell"><span class="eyebrow" style="color:#FFD928">A small action, a real difference</span><h1>Pledge what you can share.</h1><p><?=e($request['organization_name'])?> needs help with “<?=e($request['title'])?>”. Choose exact items you can confidently bring.</p></div></section>
<section class="section" style="padding-top:35px"><div class="shell" style="max-width:820px"><div class="panel"><div class="panel-heading"><h2>Your available items</h2><span class="chip">Pledge ID comes after sending</span></div><?php if($errors):?><div class="flash flash-error"><span><?=e(implode(' ',$errors))?></span></div><?php endif;?><form method="post" data-loading><?=csrf_field()?><input type="hidden" name="request_id" value="<?=$requestId?>"><?php foreach($requirements as $r):?><div class="requirement-row"><div class="form-grid"><div><h3><?=e($r['category'])?> <span class="muted">· <?=e($r['size_label'])?></span></h3><p><?=e($r['condition_note']?:'Clean and ready to wear.')?> <strong><?=$r['quantity_remaining']?> still needed</strong></p></div><div class="field"><label for="q<?=$r['id']?>">How many can you bring?</label><input class="input" id="q<?=$r['id']?>" type="number" min="0" max="<?=$r['quantity_remaining']?>" name="quantity[<?=$r['id']?>]" value="<?=e((string)($quantities[$r['id']] ?? 0))?>"></div></div></div><?php endforeach;?><div class="field" style="margin-top:16px"><label for="donor_notes">Note for the charity <small>(optional)</small></label><textarea class="textarea" id="donor_notes" name="donor_notes" maxlength="1000" placeholder="For example: I can bring these on Saturday morning."><?=e($_POST['donor_notes']??'')?></textarea></div><div class="form-actions"><a class="button button-outline" href="<?=e(url('donor/request.php?id='.$requestId))?>">Cancel</a><button class="button" type="submit">Send pledge →</button></div></form></div></div></section>
